package org.marketreview.nativeapp;
import org.json.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;
public final class LocalCandidateBackgroundChecks {
 static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 static JSONObject read(String path)throws Exception{return new JSONObject(new String(Files.readAllBytes(Paths.get(path)),StandardCharsets.UTF_8));}
 public static void main(String[]args)throws Exception {JSONObject fixture=read(args[0]);JSONArray output=new JSONArray();for(String group:new String[]{"cases","negatives"}){JSONArray cases=fixture.getJSONArray(group);for(int i=0;i<cases.length();i++){JSONObject c=cases.getJSONObject(i),r=LocalCandidateBackground.evaluate(c.getJSONObject("background"),c.getString("id"),c.getString("strategy"),Instant.parse(c.getString("capturedAt")));if(group.equals("cases")){check(r.getInt("completeDelta")==c.getInt("expectedDelta"),"actual old delta mismatch "+c.getString("name"));check(r.getString("status").equals("complete"),"known complete");}else{check(r.isNull("completeDelta"),"unknown not zero");JSONArray rules=c.getJSONArray("expectedUnknown"),factors=r.getJSONArray("factors");for(int j=0;j<rules.length();j++){boolean found=false;for(int k=0;k<factors.length();k++){JSONObject f=factors.getJSONObject(k);if(f.getString("rule").equals(rules.getString(j)))found=f.isNull("points");}check(found,"unknown rule incorrectly scored "+c.getString("name"));}}output.put(new JSONObject().put("name",c.getString("name")).put("evaluation",r));}}
  JSONArray old=read(args[1]).getJSONArray("cases");JSONObject selectedCase=null;for(int i=0;i<old.length();i++){JSONObject c=old.getJSONObject(i);if(c.has("error"))continue;JSONArray rows=c.getJSONObject("result").getJSONArray("rows");if(rows.length()>0&&rows.getJSONObject(0).opt("rawScore") instanceof Number){selectedCase=c;break;}}check(selectedCase!=null,"eligible v1 fixture");JSONArray selected=selectedCase.getJSONArray("selected");Instant at=Instant.parse(selectedCase.getString("capturedAt"));String strategy=selectedCase.getString("strategy");JSONObject baseline=LocalCandidateModel.evaluate(LocalCandidateModel.snapshot(selected,strategy,at));LocalCandidateModel.verify(baseline);check(LocalCandidateModel.VERSION.equals(baseline.getString("model")),"v1 preserved");
  JSONObject s=selected.getJSONObject(0);JSONArray cases=fixture.getJSONArray("cases");String serialized=cases.getJSONObject(cases.length()-1).getJSONObject("background").toString().replace("SH:stock:600001",s.getString("id")).replace("2026-10-13T08:00:00Z",selectedCase.getString("capturedAt")).replace("2026-10-13T07:00:00Z",selectedCase.getString("capturedAt"));s.put("backgroundInput",new JSONObject(serialized));JSONObject frozen=LocalCandidateModel.snapshot(selected,strategy,at),result=LocalCandidateModel.evaluate(frozen);LocalCandidateModel.verify(result);JSONObject baseRow=null,newRow=null;JSONArray br=baseline.getJSONArray("rows"),nr=result.getJSONArray("rows");for(int i=0;i<br.length();i++)if(br.getJSONObject(i).getString("id").equals(s.getString("id")))baseRow=br.getJSONObject(i);for(int i=0;i<nr.length();i++)if(nr.getJSONObject(i).getString("id").equals(s.getString("id")))newRow=nr.getJSONObject(i);check(LocalCandidateModel.canonical(baseRow.getJSONObject("factors")).equals(LocalCandidateModel.canonical(newRow.getJSONObject("factors"))),"technical factors unchanged");check(newRow.getInt("rawScore")==baseRow.getInt("rawScore")+newRow.getJSONObject("backgroundEvaluation").getInt("knownDelta"),"apply delta once before clamp");int sum=0;JSONArray contributions=newRow.getJSONArray("contributions");for(int i=0;i<contributions.length();i++)sum+=contributions.getJSONObject(i).getInt("points");check(sum==newRow.getInt("rawScore"),"contributions conserve raw score");check(result.getString("model").equals(LocalCandidateBackground.CANDIDATE_VERSION),"v2 model");check(!result.getString("inputHash").equals(baseline.getString("inputHash")),"input hash binds background");check(new String(LocalCandidateModel.csv(result),StandardCharsets.UTF_8).contains(LocalCandidateBackground.CANDIDATE_VERSION),"CSV actual model");JSONObject bad=new JSONObject(result.toString());bad.getJSONArray("rows").getJSONObject(0).put("rawScore",999);boolean rejected=false;try{LocalCandidateModel.verify(bad);}catch(Exception e){rejected=true;}check(rejected,"tamper rejected");Thread.currentThread().interrupt();rejected=false;try{LocalCandidateModel.evaluate(frozen);}catch(InterruptedException e){rejected=true;}finally{Thread.interrupted();}check(rejected,"cancelled");
  JSONObject excluded=new JSONObject().put("id",s.getString("id")).put("score",JSONObject.NULL).put("rawScore",JSONObject.NULL).put("status","excluded").put("contributions",new JSONArray()).put("missing",new JSONArray());JSONObject applied=LocalCandidateBackground.apply(excluded,s.getJSONObject("backgroundInput"),strategy,at);check(applied.isNull("score")&&applied.getString("status").equals("excluded"),"background cannot rescue excluded technical input");
  Files.write(Paths.get(args[2]),output.toString().getBytes(StandardCharsets.UTF_8));System.out.println("PASS JVM: 128 actual-old deltas, 20 adversarial inputs, v1/v2 replay, digest/tamper/CSV/cancel/exclusion");
 }
}


